    /**
     * Restrict the namespaces this engine reads (empty: all); those newly in scope are read now.
     */
    fun `setReadScope`(`namespaces`: List<kotlin.String>): Changes
    
    /**
     * Faults of the record source the host must show (it changed bytes it must never change).
     */
    fun `sourceFaults`(): List<SourceFault>
    
    /**
     * What the destination already holds of a copy of `library`.
     */
    fun `swiftCopyDestination`(`library`: kotlin.String): SwiftCopyDestination
    
    /**
     * The verified Swift predecessor history this account holds.
     */
    fun `swiftPredecessor`(): SwiftPredecessor
    
    /**
     * Where the Swift succession this account claims stands (§15.1).
     */
    fun `swiftSuccession`(): SwiftSuccession
    
    /**
     * Seal the opened vault seed to the confirmed pairing's device.
     */
    fun `transferSeed`(`pairing`: AccountPairing, `entropy`: kotlin.ByteArray): SealedSeed
    
    /**
     * The paths whose provider versions the next `refresh` wants, for one batched provider call.
     */
    fun `versionPaths`(`listing`: List<kotlin.String>): List<kotlin.String>
    
    /**
     * The session view of the verified history at `at_ms` (wall clock) for an endpoint of
     * `namespace`: every member current then, with its session number and `records` entries,
     * stamped with this engine, the account, the namespace and the authority head.
     */
    fun `sessionAccount`(`namespace`: kotlin.String, `atMs`: kotlin.Long): SessionAccountView
    
    /**
     * Prepare the `colophon.home.stream` call that mints a ticket at `home`, signed by this
     * session's own `key`. 32 bytes of entropy (the request ID). `finish` judges it by the home's
     * own rule and returns the envelope as `artifact`, for `HomeStream.ticket_request`. Before
     * the first pass with the home this is `Unavailable` (no fresh head): call
     * `ticket_call_failed`.
     */
    fun `streamBeginCall`(`home`: kotlin.String, `key`: kotlin.ByteArray, `entropy`: kotlin.ByteArray): AccountAction
    
    /**
     * A stream client for `home`, at the home's first endpoint, resuming from `cursor`; the
     * safety poll is lowered to the account's `recoveryDelay / 6` when that is shorter, and the
     * client starts at the verified history's seq.
     */
    fun `streamClient`(`home`: kotlin.String, `config`: StreamConfig, `cursor`: kotlin.String?): HomeStream
    
    companion object
}

/**
 * The account engine over a host record source.
 */
open class AccountEngine: Disposable, AutoCloseable, AccountEngineInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_colophon_ffi_fn_free_accountengine(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
