sealed class ViewOutcome {
    
    data class Success(
        val `value`: com.luff.colophon.NamespaceView) : ViewOutcome()
        
    {
        

        companion object
    }
    
    data class Failure(
        val `denial`: com.luff.colophon.Denial) : ViewOutcome()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeViewOutcome : FfiConverterRustBuffer<ViewOutcome>{
    override fun read(buf: ByteBuffer): ViewOutcome {
        return when(buf.getInt()) {
            1 -> ViewOutcome.Success(
                FfiConverterTypeNamespaceView.read(buf),
                )
            2 -> ViewOutcome.Failure(
                FfiConverterTypeDenial.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ViewOutcome): ULong = when(value) {
        is ViewOutcome.Success -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeNamespaceView.allocationSize(value.`value`)
            )
        }
        is ViewOutcome.Failure -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDenial.allocationSize(value.`denial`)
            )
        }
    }

    override fun write(value: ViewOutcome, buf: ByteBuffer) {
        when(value) {
            is ViewOutcome.Success -> {
                buf.putInt(1)
                FfiConverterTypeNamespaceView.write(value.`value`, buf)
                Unit
            }
            is ViewOutcome.Failure -> {
                buf.putInt(2)
                FfiConverterTypeDenial.write(value.`denial`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





